/*
 * A082381  Sequence of the squared digital root of a number until 1 or 4 is
 *          reached. The initial numbers 1,2,..n are not output.
 * https://oeis.org/A082381
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy, tabf
 * Formula:   not stated
 * Range:     u8 n <= 72, u16 n <= 72, u32 n <= 72, u64 n <= 72, u128 n <= 72,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence generated by concatenating all intermediate values obtained by repeatedly
 * applying f(x)=∑(digit²) to successive starting integers, stopping when the
 * result is 1 or 4 inclusive.  The sequence starts with
 * a(1)=1 from the chain 1→1, a(2)=4 from 2→4, etc. */

#include <stdlib.h>
#include <stdbool.h>

/* static storage for generated terms */
static seq_t *seq      = NULL;   /* array of computed a(k) */
static size_t seq_size = 0;      /* number of terms stored           */
static size_t seq_cap  = 0;      /* allocated capacity               */

/* state of the current chain */
static bool    initialized = false;   /* whether we have produced the first term yet */
static idx_t   curr_start = 1;        /* current starting integer being processed   */
static seq_t   curr_val;              /* current value that will be output next      */

/* Append a value to the static array, expanding it if necessary */
static void append_value(seq_t val)
{
    if (seq_size >= seq_cap) {
        size_t new_cap = seq_cap ? seq_cap * 2 : 64;
        seq = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
        seq_cap = new_cap;
    }
    seq[seq_size++] = val;
}

/* sum of squares of the decimal digits of x */
static seq_t digit_square_sum(seq_t x)
{
    seq_t sum = 0;
    while (x > 0) {
        seq_t d = x % 10;
        sum += d * d;
        x /= 10;
    }
    return sum;
}

/* Produce the next term in the overall sequence.  It updates the static
 * generation state so that successive calls yield successive terms.  */
static seq_t next_term(void)
{
    seq_t next;

    if (!initialized) {
        /* first term: apply to starting integer 1 */
        curr_val = digit_square_sum((seq_t)curr_start);
        initialized = true;
        return curr_val;
    }

    if (curr_val == 1 || curr_val == 4) {
        /* chain finished: advance to the next starting integer */
        ++curr_start;
        next = digit_square_sum((seq_t)curr_start);
    } else {
        /* continue current chain */
        next = digit_square_sum(curr_val);
    }
    curr_val = next;
    return next;
}

/* a(n) – nth term of the sequence */
seq_t a(idx_t n)
{
    while (seq_size < n) {
        seq_t val = next_term();
        append_value(val);
    }
    return seq[n - 1];
}
